import sys

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    n = int(input_data[0])
    requests = input_data[1:n+1]

    db = {}

    for name in requests:
        if name not in db:
            db[name] = 0
            print("OK")
        else:
            count = db[name]
            while True:
                count += 1
                candidate = f"{name}{count}"
                if candidate not in db:
                    break
            db[candidate] = 0
            db[name] = count
            print(candidate)

if __name__ == "__main__":
    main()
